#!/usr/bin/env python3
"""Write the owned final imaging handoff and complete artifact inventory."""
from imaging_common import *
from datetime import datetime
from zoneinfo import ZoneInfo


def main():
    t=ImagingTask('')
    validation=json.loads(t.record(OUT/'validation/validation.json').read_text());assert validation['passed']
    components=pd.read_csv(t.record(OUT/'roi/headline_early_component_balance.csv'))
    headline=pd.read_csv(t.record(OUT/'roi/headline_tidy_all_specifications.csv'))
    perm=pd.read_csv(t.record(OUT/'voxelwise/permutation_summary.csv'))
    repeat=pd.read_csv(t.record(OUT/'event_motion_diagnostics/repeat_counts_by_condition.csv'))
    motion=pd.read_csv(t.record(OUT/'event_motion_diagnostics/phase_motion_summary.csv'))
    gate=json.loads(t.record(OUT/'voxelwise_runtime_gate/validation.json').read_text())
    controls=pd.read_csv(t.record(OUT/'controls/reproduction_checks.csv'))
    qfirst=json.loads(t.record(OUT/'first_level/validation.json').read_text())
    qroi=json.loads(t.record(OUT/'roi/validation.json').read_text())
    for name in ['controls','first_level','event_motion_diagnostics','roi','voxelwise_runtime_gate','voxelwise_inputs','voxelwise','validation']:
        t.record(OUT/name/'input_manifest.json');t.record(OUT/name/'validation.json')
    main_balance=components[components.cohort.eq('N22')&components.model.eq('reference')&components.component.eq('condition_mean')]
    main_early=headline[headline.cohort.eq('N22')&headline.stage.eq('early')]
    now=datetime.now(ZoneInfo('Asia/Taipei')).isoformat(timespec='seconds')
    report='# R1 imaging completed — '+now+'\n\nStatus: **DONE WITH DEVIATIONS**. Completed A2–A6 and the joint192-slot A1 rule for new imaging variants, in the owned namespace only. N22 uncensored reference/observed80 remains primary; N20 is supplement-only. No manuscript changes, publications, external messages, Git writes, installs or new out-of-scope analyses were performed.\n\n## Implemented analyses\n\n- `first_level/`: all five fixed variants ×22 participants ×8 runs, 880 fits; full design/QC and observed80 condition values. Only censored-spike maps are retained for the authorized voxelwise rerun. All use Glover/cosine1/128s/AR(1)/4-mm smoothing, all200rows, mean scaling identical to the reference.\n- `controls/`: before the full run, the two specified reference controls and full expanded-nuisance stage values for both control participants reproduced existing values. The all-participant expanded-cell stage comparison is in `roi/participant_acompcor_stage_reproduction.csv`.\n- `roi/`: reference, row-deletion censored comparator and five new variants, all stages and both cohorts. Stage BH48, joint-stage BH192, direct-phase BH144, full paired ΔS/ΔR/M tables and early headline BH4. `headline_tidy_all_specifications.csv` combines the four headline regions across all specifications. All48ROI slots are retained, with untestable p=1 for BH; CIs are pointwise.\n- `event_motion_diagnostics/`: D1 counts by condition/run and block boundary, participant run/phase motion burden and descriptive paired phase comparisons. Acquisition times in corrected boxcars define condition membership; group phase summaries equally average the two runs within participant.\n- `voxelwise_runtime_gate/`, `voxelwise_inputs/`, `voxelwise/`: measured gate and all10 matched censored-spike analyses,10000permutations each. Same58550-voxel mask, validated direct TFCE backend and separate historical-stage/pooled families as existing censored runs. Raw nulls, maps, components and descriptive row-deletion comparison are saved.\n- `validation/`: independent arithmetic from participant values, all BH families, D1 counts, spike columns, rank/df, unique first-level input hashes and saved output hashes.\n\n## Neutral results\n\nN22 reference M=(ΔS+ΔR)/2 in the four early regions (phase-mean scale; pointwise95%CI; q is four-slot headline BH):\n\n```text\n'+main_balance[['roi','n','mean','ci_low','ci_high','p','q_headline_early_4']].to_string(index=False)+'\n```\n\nThe fixed wording rule permits declining-random attribution only where M CI lies entirely below zero; all other rows are explicitly marked relative contributions unresolved in the tidy table. Component results do not establish an absent structured increase, and these sensitivities do not convert prior exploratory findings into independent confirmation.\n\nN22 early stage estimates across specifications (summed DiD scale; full intervals and q values):\n\n```text\n'+main_early[['model','roi','mean','ci_low','ci_high','q','q_joint_stages_192']].to_string(index=False)+'\n```\n\nD1 target-repeat counts:\n\n```text\n'+repeat.to_string(index=False)+'\n```\n\nTarget is raw `keypress`, not observed response `p_response_keys`; existing source-validation code compares it against condition-list targets. D1 requires the immediately preceding same-run trial slot, equal target and exactly1-s onset separation, regardless of condition/block. No errors/omissions are excluded. All48 gap-separated Random pairs from preflight are excluded; no included repeats cross a logged block boundary.\n\nN22 paired structured−random motion/censoring burden (descriptive, no correction):\n\n```text\n'+motion[motion.cohort.eq('N22')&motion.contrast.eq('structured_minus_random')][['phase','metric','n','mean','ci_low','ci_high','p']].to_string(index=False)+'\n```\n\nCensored-spike TFCE counts:\n\n```text\n'+perm.to_string(index=False)+'\n```\n\nThreshold/count differences are descriptive, not tests of model differences, motion causation or mediation. BA6 keys LeftSMA/RightSMA refer to full parcels. No new brain–behavior, awareness or other whole-brain analyses were added.\n\n## Deviations and implementation clarifications\n\n1. **D1, coordinator/user authorized before A5 outcomes:** the initial blocked preflight found48gap-separated Random boundary repeats. The user directed the amended plan definition, excluding fixation/trigger gaps and allowing any condition/boundary when onset separation is exactly1s. That definition was applied without outcome selection.\n2. **2026-10-19, logged before outcome interpretation:** sub-020 run5 has only five retained combined-mask aCompCor components. The required identical selection `components[:8]` from updated_targeted_sensitivity.py uses those five; both aCompCor cells do likewise. No discarded or separate-mask components were substituted. This is an input exception to the nominal8-component label. The historical expanded cell reproduces. A stricter initial availability assertion detected this before fitting that run.\n3. **A4 seed clarification:** the specific same-seed instruction uses existing20261018, rather than general R1 default20261019. This preserves the exact existing censored permutation definition and eight-chunk schedule. No stochastic seed is used for deterministic ROI fits.\n4. Historical backend replay timing used a mask61voxels larger than the required mask. Its equality check failed before new inference; the accepted gate instead timed1000permutations of existing N22 censored maps on the exact mask. No inference specification changed.\n5. A report renderer initially requested unavailable optional `tabulate`; it was replaced with plain pandas text output without installing packages or changing analyses. Earlier failed commands and corrected commands are retained in assigned scratch.\n\n## Commands, runtimes and checks\n\nAll Python commands used `/media/data3/chiaoen_srtt/envs/nilearn-0131/bin/python -B`, with `PYTHONDONTWRITEBYTECODE=1`. No more than4first-level CPU workers or8permutation workers were used; these phases were sequential.\n\n```sh\npython -B code/review_r1/imaging_preflight.py\npython -B code/review_r1/imaging_fits.py controls --workers 4\npython -B code/review_r1/imaging_summaries.py diagnostics\npython -B code/review_r1/imaging_fits.py full --workers 4\npython -B code/review_r1/imaging_summaries.py roi\npython -B code/review_r1/imaging_voxelwise.py gate\npython -B code/review_r1/imaging_voxelwise.py prepare\npython -B code/review_r1/imaging_voxelwise.py run\npython -B code/review_r1/imaging_validate.py\npython -B code/review_r1/imaging_finalize.py\n```\n\nRead-only inspection used cat/sed/head,rg,ls,pwd,git status,ps and small Python diagnostics. Full command logs are in `/tmp/r1-r1-imaging/`; per-run runtime/QC is in each new qc.json. Controls:\n\n```text\n'+controls.to_string(index=False)+'\n```\n\nFull-run orchestration elapsed '+str(qfirst['elapsed_seconds'])+' s; minimum residual df '+str(qfirst['min_residual_df'])+'. Full expanded-cell stage maximum difference '+str(qroi['max_expanded_stage_reproduction_difference'])+'. A4 timed1000-permutation batch '+str(gate['measured_censored_batch_seconds'])+' s; projected total with twofold margin '+str(gate['projected_total_seconds_with_twofold_margin'])+' s (limit10800s); actual full permutation total '+str(float(perm.permutation_seconds.sum()))+' s. Independent validator results:\n\n```json\n'+json.dumps({k:v for k,v in validation.items() if k not in ['output_sha256']},indent=2)+'\n```\n\nEvery analysis directory contains REPORT.md,validation.json,input_manifest.json and machine-readable CSVs. Complete created-file SHA256 inventory is `results/glm_volume/review_r1_20261019/files_created.csv` (excluding itself and the root validation.json to avoid a hash cycle); the root validation hashes this inventory. It includes this handoff and all owned imaging code/results. Historical preflight scratch hashes remain recorded in its manifest and logs.\n\n## Limits and next step\n\nAll requested imaging computation is completed within the documented input exception. The independent r1-audit coordinator review, protected-file baseline comparison, and user review remain; no manuscript/UI/build verification is claimed. Shared MANUSCRIPT_STATUS/REVISION_LOG were not edited because this role owns only the listed imaging code/results and this report. The coordinator should incorporate this completed/pending state and the deviations in the shared handoff, then obtain user review before manuscript integration.\n'
    (ROOT/'docs/review_round1/reports/r1-imaging.md').write_text(report)
    summary=dict(passed=True,completed=['A2','A3','A4','A5','A6','A1_new_imaging_variants'],n_first_level_fits=880,
                 n_voxelwise_analyses=10,n_permutations_each=10000,deviations=['D1_authorized_repeat_definition','five_retained_components_sub020_run5'],
                 manuscript_modified=False,independent_auditor_review_pending=True)
    t.finish(report,summary)
    paths_created=list((ROOT/'code/review_r1').glob('imaging_*.py'))+[ROOT/'docs/review_round1/reports/r1-imaging.md']
    paths_created += [p for p in OUT.rglob('*') if p.is_file() and p not in [OUT/'files_created.csv',OUT/'validation.json']]
    csv([dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,sha256=digest(p)) for p in sorted(paths_created)],OUT/'files_created.csv')
    rootq=json.loads((OUT/'validation.json').read_text());rootq['output_sha256']['files_created.csv']=digest(OUT/'files_created.csv');writej(OUT/'validation.json',rootq)
    print('Created-file inventory rows:',len(paths_created),flush=True)


if __name__=='__main__':main()
